370	    fn test_keymap_disabled() {
371	        let bindings = [
372	            KeyBinding::new("ctrl-a", ActionAlpha {}, Some("editor")),
373	            KeyBinding::new("ctrl-b", ActionAlpha {}, Some("editor")),
