732	    /// Models the picker preview footer scenario: a picker action is bound in
733	    /// `Picker > Editor`, but a base keymap binds the same chord to an editor
734	    /// action in `Editor`. `Picker > Editor` and `Editor` resolve at the same
735	    /// context depth, so at equal depth precedence is decided purely by load
736	    /// order (later wins). Because base keymaps load after the default keymap,
737	    /// the picker binding is shadowed unless it is (re)bound by an overlay that
738	    /// loads after the base keymap - which is exactly what
739	    /// `keymaps/specific-overrides*.json` does.
740	    #[test]
741	    fn test_overlay_after_base_restores_shadowed_picker_binding() {
742	        // SecondaryTestAction stands in for the editor/base action (e.g.
743	        // editor::AddSelectionBelow), TestAction for the picker action.
744	        let contexts = vec![
745	            KeyContext::parse("Picker").unwrap(),
746	            KeyContext::parse("Editor").unwrap(),
747	        ];
748	
749	        // Default keymap (picker binding) followed by a base keymap that binds
750	        // the same chord to an editor action: the base binding wins and the
751	        // picker action is shadowed, so its footer tooltip renders no shortcut.
752	        let shadowed = test_dispatch_tree(vec![
753	            KeyBinding::new("ctrl-alt-down", TestAction, Some("Picker > Editor")),
754	            KeyBinding::new("ctrl-alt-down", SecondaryTestAction, Some("Editor")),
755	        ]);
756	        let highest = shadowed.highest_precedence_binding_for_action(&TestAction, &contexts);
757	        assert!(
758	            highest.is_none(),
759	            "picker binding should be shadowed by the base editor binding"
760	        );
761	
762	        // Re-binding the picker action in an overlay loaded after the base keymap
763	        // restores it as the resolved binding.
764	        let fixed = test_dispatch_tree(vec![
765	            KeyBinding::new("ctrl-alt-down", TestAction, Some("Picker > Editor")),
766	            KeyBinding::new("ctrl-alt-down", SecondaryTestAction, Some("Editor")),
767	            // overlay loaded last:
768	            KeyBinding::new("ctrl-alt-down", TestAction, Some("Picker > Editor")),
769	        ]);
770	        let highest = fixed.highest_precedence_binding_for_action(&TestAction, &contexts);
771	        assert!(
772	            highest.is_some_and(|binding| binding.action.partial_eq(&TestAction)),
773	            "overlay loaded after base should restore the picker binding"
774	        );
775	
776	        // Conversely, putting the override in the default keymap (i.e. before the
777	        // base keymap) does NOT help: the later base binding still wins at equal
778	        // depth. This is why the overlay must be loaded after the base keymap.
779	        let override_before_base = test_dispatch_tree(vec![
780	            KeyBinding::new("ctrl-alt-down", TestAction, Some("Picker > Editor")),
781	            KeyBinding::new("ctrl-alt-down", TestAction, Some("Picker > Editor")),
782	            KeyBinding::new("ctrl-alt-down", SecondaryTestAction, Some("Editor")),
783	        ]);
784	        let highest =
785	            override_before_base.highest_precedence_binding_for_action(&TestAction, &contexts);
786	        assert!(
787	            highest.is_none(),
788	            "an override loaded before the base binding cannot win the equal-depth tie"
789	        );
790	    }
