fn main() {
    application().run(|cx: &mut App| {
        // 同名动作、同一按键、两个上下文：焦点决定哪条生效。
        // Search 在栈的更深处（depth 2 > depth 1），焦点在搜索框时它必然胜出。
        cx.bind_keys([
            gpui::KeyBinding::new("cmd-t", Toggle, Some("Editor")),
            gpui::KeyBinding::new("cmd-t", Toggle, Some("Search")),
            gpui::KeyBinding::new("tab", gpui::actions_names_demo_dummy(), None)
                .with_meta(gpui::KeyBindingMetaIndex(0)),
        ]);
        cx.open_window(WindowOptions::default(), |window, cx| {
            let search = cx.new(|cx| SearchBox {
                focus_handle: cx.focus_handle(),
                log: "".into(),
            });
            let editor = cx.new(|cx| EditorPanel {
                search: search.clone(),
                focus_handle: cx.focus_handle(),
                log: "".into(),
            });
            editor.focus_handle(cx).focus(window, cx);
            editor
        })
        .unwrap();
    });
}
```

上面 `main` 里第三条 `bind_keys` 的 dummy 写法不可编译，实际操作时请删掉它——**tab 切换焦点不需要手动绑定**：GPUI 的 tab 导航由焦点系统内置处理（u5-l5 详解）。保留前两条即可：

```rust
cx.bind_keys([
    gpui::KeyBinding::new("cmd-t", Toggle, Some("Editor")),
    gpui::KeyBinding::new("cmd-t", Toggle, Some("Search")),
]);
```

